const MENU_PREVIEW_PRESS_STYLE: React.CSSProperties = {
  background: "var(--color-background-brand-light-slate)",
  color: "var(--color-text-brand-strong)",
  boxShadow:
    "inset 0 1px 0 0 var(--color-border-brand-base-neutral), inset 0 -1px 0 0 var(--color-border-brand-base-neutral)",
};

const MENU_PREVIEW_FOCUS_STYLE: React.CSSProperties = {
  background: "var(--color-background-surface-component)",
  borderRadius: "var(--corner-radius-radius-4, 4px)",
  boxShadow:
    "inset 0 0 0 var(--border-width-border-default, 1px) var(--color-border-brand-base)",
};

function MenuPreviewOption({
  label,
  state = "default",
  submenu = false,
  chevronSide = "right",
}: {
  label: string;
  state?: "default" | "hover" | "press" | "selected" | "disabled" | "focus" | "submenuOpen";
  submenu?: boolean;
  chevronSide?: "left" | "right";
}) {
  const stateAttrs: Record<string, string> = {};
  const style: React.CSSProperties = {};
  if (state === "hover") stateAttrs["data-highlighted"] = "";
  if (state === "selected") stateAttrs["data-selected"] = "true";
  if (state === "disabled") stateAttrs["data-disabled"] = "";
  if (state === "submenuOpen") stateAttrs["data-popup-open"] = "";
  if (state === "press") Object.assign(style, MENU_PREVIEW_PRESS_STYLE);
  if (state === "focus") Object.assign(style, MENU_PREVIEW_FOCUS_STYLE);

  return (
    <li role="presentation">
      <button
        type="button"
        className={[
          menuStyles.optionItem,
          menuStyles.submenuFlyoutItem,
          submenu ? menuStyles.submenuParent : "",
        ]
          .filter(Boolean)
          .join(" ")}
        style={style}
        {...stateAttrs}
      >
        <span>{label}</span>
        {submenu ? (
          <span className={menuStyles.submenuChevron} aria-hidden>
            <Icon
              shapeName={chevronSide === "left" ? "chev-left" : "chev-right"}
              style={{ width: 16, height: 16 }}
            />
          </span>
        ) : null}
      </button>
    </li>
  );
}

